(()=>{"use strict";const U=GU,{$,esc,num,money,table,stat,panel,flow,detail,link,source,bars,chart,lab,steps,quiz,interview}=U,G=GUIDE,C=CONTENT;
const qNames=G.chapters.map(x=>x[0]),finance=G.finance,caseNames=G.cases,clients=G.clients;let route="home",sharing=false,notes={};try{notes=JSON.parse(localStorage.getItem("bell_guided_notes_v3")||"{}")}catch{}let save=()=>{try{localStorage.setItem("bell_guided_notes_v3",JSON.stringify(notes))}catch{}};
const items={
q1:[["orientation","Start here: What is FP&A?"],["skills","My existing skills"],["atlas","My Learning Atlas"],...finance.map(v=>[v[0],v[1]]),["excel","Excel: work with cells"],["sql","SQL: combine tables"],["bi","BI: report and drill down"],["ai","AI: permission and checking"],["ux","UI/UX: design a useful report"],["ml","Machine learning: test a forecast"],["q1-answer","Interview answer and learning plan"]],
q2:[["overview","Experience map"],...caseNames.map(v=>[v[0],v[2]])],
q3:[["research","Research a company first"],["discovery","Client discovery process"],["review","StudioCo: source-to-report review"],...clients.map(v=>[v[0],v[1]]),["handover","Monthly handover & next review"],["capacity","Service capacity"],["retailer","Transfer to a retailer"]],
q4:[["company","Why Canva? Customer and product"],["plans","Plans and how revenue starts"],["competitors","Visual competitor comparison"],["retention","Customer retention and recurring revenue"],["cost","Cost to serve and contribution"],["increment","AI distribution and extra customers"],["findings","Research findings and unexpected insights"],["pilot","Investment: scenarios and cash"],["decision","Recommendation and next evidence"],["canva-questions","Questions to ask Canva"],["defence","Present and defend the case"]],
q5:[["firm","Understand Inspired Financials"],["questions","Questions and follow-ups"],["reflection","Private reflection (optional)"]]
};
function logo(name,file){return '<img class="brandlogo" src="brands/'+file+'.svg" alt="'+esc(name)+' logo" onerror="this.hidden=true">'}
function nav(){let q=route.split("/")[0];$("topnav").innerHTML=[["home","Home"],...qNames.map((t,i)=>["q"+(i+1)+"/"+items["q"+(i+1)][0][0],String(i+1).padStart(2,"0")+" "+t]),["rehearse","Rehearse"]].map(([p,t])=>'<a href="#'+p+'" class="'+((q===p||p.startsWith(q+"/"))?"active":"")+'">'+esc(t)+'</a>').join("")}
function home(){return '<div class="hero"><div class="eyebrow">Inspired Financials · Stage 2 · Five interview topics</div><h1>Prepare. Understand.<br>Present.</h1><p class="lead">One learning journey through financial planning, my experience, client decisions and a real company case. Learn the examples here, then explain the exact same examples in the interview.</p></div><div class="start"><div><div class="eyebrow">New to FP&A? Start here</div><h2>What does an FP&A analyst actually do?</h2><p>Start with a simple business, profit and cash. No previous FP&A experience required.</p></div><a class="btn primary" href="#q1/orientation">Start learning →</a></div><div class="agenda">'+G.chapters.map((v,i)=>'<a href="#q'+(i+1)+'/'+v[3]+'"><div class="symbol" style="--tint:'+v[5]+';--accent:'+v[4]+'"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+v[6]+'"/></svg></div><div><div class="eyebrow" style="color:'+v[4]+'">QUESTION 0'+(i+1)+'</div><h2>'+esc(v[0])+'</h2><p>'+esc(v[1])+'</p><small>'+esc(v[2])+'</small><span style="display:inline-block;margin-top:10px;color:'+v[4]+';font-weight:700">Open section →</span></div></a>').join("")+'</div><section class="panel"><h2>Recommended order</h2>'+flow(["Learn foundations","Review 3 strongest cases","Research & client practice","Canva case","Questions","Rehearse"])+'<p>Start with foundations, then follow James’s questions. You can return to any lesson using Home or the topic menu.</p>'+link("rehearse","Interview rehearsal")+'</section>'}
function noteBox(){let n=notes[route]||{};return '<section class="note practice-only"><h3>My practice notes</h3><p class="caption">Optional. Only saved on this browser if you choose Save. Not authenticated or synced. Do not enter confidential information. Hide notes before screen sharing.</p><label>Your answer<textarea id="practice-answer" placeholder="Explain the lesson in your own words…">'+esc(n.text||"")+'</textarea></label><label>Readiness <select id="readiness">'+["Not started","Reviewed","Practised","Can explain","Can defend"].map(v=>'<option '+(n.ready===v?"selected":"")+'>'+v+'</option>').join("")+'</select></label><div class="toolbar"><button id="save-note">Save on this browser</button><button id="clear-note">Clear this note</button><button id="clear-all">Clear all notes</button></div><div id="note-status" aria-live="polite"></div></section>'}
function shell(q,id,body){let arr=items[q],idx=arr.findIndex(x=>x[0]===id),chapter=Number(q[1]),title=arr[idx][1];return '<div class="trail"><a href="#home">Home</a> › <span>Question '+chapter+' · '+esc(qNames[chapter-1])+'</span> › <span>Lesson '+(idx+1)+' of '+arr.length+'</span></div><div class="lesson-layout"><aside class="sidebar" aria-label="Lesson menu"><div class="eyebrow">Question '+chapter+'</div><h3>'+esc(qNames[chapter-1])+'</h3>'+arr.map(([k,t],i)=>'<a href="#'+q+'/'+k+'" class="'+(k===id?"active":"")+'">'+(i+1)+'. '+esc(t)+'</a>').join("")+'</aside><article class="lesson"><div class="eyebrow">Question 0'+chapter+' / Lesson '+(idx+1)+'</div><h1>'+esc(title)+'</h1>'+body+noteBox()+'<div class="footer-nav">'+(idx?link(q+"/"+arr[idx-1][0],"← "+arr[idx-1][1]):link("home","← Interview home"))+(idx<arr.length-1?'<a class="btn primary" href="#'+q+'/'+arr[idx+1][0]+'">Next: '+esc(arr[idx+1][1])+' →</a>':chapter<5?'<a class="btn primary" href="#q'+(chapter+1)+'/'+items["q"+(chapter+1)][0][0]+'">Next question →</a>':link("rehearse","Rehearse interview"))+'</div></article></div>'}
function financeContent(id){let v=finance.find(x=>x[0]===id);if(id==="orientation"||id==="cash"){let intro=id==="orientation"?'<p class="lead">FP&A means Financial Planning and Analysis. It helps a company understand what happened, what may happen next, and what it should do.</p>'+panel("FROM ACCOUNTING TO DECISIONS","The job in four steps",flow(["Transactions","Actual results","Future forecast","Management decision"])+'<div class="four">'+["Accounting records transactions.","Reporting summarises results.","FP&A uses actual results and assumptions to forecast.","Management compares choices and decides."].map((x,i)=>'<div class="stat"><small>Step '+(i+1)+'</small><p>'+x+'</p></div>').join("")+'</div><p>Start with the accounting you already know. Then learn how to use it to plan future payments and decisions.</p>'):'<p class="lead">We will use the same November service business example to understand why earning revenue is different from receiving money.</p>';return intro+panel("1 · START WITH WHAT YOU KNOW","Income statement and bank balance are different",'<div class="columns"><div class="statement"><h3>Income statement (P&L)</h3><p>Sales revenue − cost of sales = gross profit. Then subtract other expenses to find profit. Revenue is recorded when earned; expenses when incurred, not necessarily when paid.</p></div><div class="statement"><h3>Cash flow and bank balance</h3><p>Cash flow tracks actual receipts and payments. Opening cash is the money already in the bank before the period. Closing cash is what remains after movements.</p></div></div><p>In this simplified service business, RM6,000 of wages is the only expense shown. We are not building a complete income statement with separate cost of sales, overhead and tax.</p>')+panel("2 · FOLLOW THE EVENTS","Where does every number come from?",'<div class="timeline-cash"><div class="timecard"><small>1 NOVEMBER</small><h3>RM4,000 already in bank</h3><p>Imagine you open the bank app on the first day of November. This is the existing balance from earlier business activity or funding. It is an assumed starting point, not money from the new sale.</p></div><div class="timecard"><small>10 NOVEMBER</small><h3>RM10,000 work completed</h3><p>You finish the work and issue an invoice. The customer agrees to pay in December. You earned revenue of RM10,000, but the bank has not received any of it yet.</p><div class="formula">Dr Accounts receivable RM10,000<br>Cr Service revenue RM10,000</div></div><div class="timecard"><small>30 NOVEMBER</small><h3>RM6,000 wages due</h3><p>The wages are a November expense. If only RM4,000 is available and no other cash arrives, you cannot pay all RM6,000 without finding RM2,000 of funding or agreeing a change in payment timing.</p></div><div class="timecard"><small>DECEMBER</small><h3>Customer transfers RM10,000</h3><p>Now the bank receives the money and the customer no longer owes it. This is cash received in December, but it is not new December revenue.</p><div class="formula">Dr Bank RM10,000<br>Cr Accounts receivable RM10,000</div></div></div>')+panel("3 · SEE BOTH CALCULATIONS","Why RM4,000 profit does not mean RM4,000 in the bank",'<div class="columns"><div class="statement"><h3>November income statement</h3>'+table(["Item","RM"],[["Revenue earned","10,000"],["Wage expense","(6,000)"],["Profit","<b>4,000</b>"]])+'<p>The accounting profit happens because the work was completed and wages incurred.</p></div><div class="statement"><h3>November cash forecast</h3>'+table(["Item","RM"],[["Cash already in bank on 1 Nov","4,000"],["New cash received from customer","0"],["Wages due by 30 Nov","(6,000)"],["Projected cash shortage","<b>(2,000)</b>"]])+'<p>Zero receipts means the customer has not transferred any money yet. The negative number is an unmet funding need, not an assumption that a real bank permits negative cash.</p></div></div><div class="callout"><b>Two different RM4,000 figures</b><p>The RM4,000 starting bank balance and the RM4,000 profit happen to be the same in this example. They are unrelated. Change the starting bank balance to RM8,000 below and see that profit stays RM4,000.</p></div>')+panel("4 · TRY ONE CHANGE AT A TIME","What if the customer pays earlier?",'<p>First move only the invoice payment slider from 0% to 100%. Notice that November revenue and profit stay the same, while cash improves. Then reset and change the opening bank balance.</p><div id="finance-lab"></div><h3>Check your understanding</h3><div id="finance-quiz"></div>')+(id==="orientation"?panel("CLIENT WORK","A typical monthly cycle",flow(["Understand business","Request data","Check","Explain","Forecast","Decide","Review again"])+'<p>Xero is an accounting system, HubSpot a customer/deal system, and Chargebee a subscription and billing system. Orders, invoices and cash are different. The exact client systems and review process must be agreed with the founder.</p>'+link("q3/research","Learn how to research a client")):"")+interview("How can a profitable business have a cash shortage?","Profit records revenue when earned and expenses when incurred. Cash depends on when customers actually pay and when bills are due. I would compare the opening bank balance, expected receipts and payments to identify any funding gap.","Why is collecting a November invoice in December not new revenue? The revenue was already earned in November; collecting it reduces receivables and increases bank cash.","Show the two reports and change the payment timing. Explain each input before showing the result.")}return '<p class="lead">'+esc(v[2])+'</p>'+panel("A–B · UNDERSTAND",v[1],'<p>'+esc(v[3])+'</p><div class="formula">'+esc(v[4])+'</div><p>'+esc(v[5])+'</p>')+panel("C–G · WORKED EXAMPLE & LIVE EXPERIMENT","Change a value and watch the result",'<p>'+esc(v[6])+'</p><div id="finance-lab"></div><h3>Check your understanding</h3><div id="finance-quiz"></div>')+interview(v[7],v[8],"What information would you need from an actual client to replace these fictional assumptions?","Explain the fixed example, change one input and describe the business effect.")}
function skillPage(){return '<p class="lead">My professional foundation is accounting, reporting, data checks and automation. I want to use those skills to develop commercial FP&A.</p>'+panel("SKILLS MAP","My foundation",flow(["Finance & accounting","Data & reporting","Technology","Business systems"])+'<div class="columns">'+G.skills.map(v=>'<article class="stat"><h3>'+esc(v[0])+'</h3><p>'+esc(v[1])+'</p><p class="caption">'+esc(v[2])+'</p>'+link(v[3],"Explore example")+'</article>').join("")+'</div>')+interview("What can you already do, and what do you want to learn?","My current strengths are accounting, financial reporting, Excel, Tableau, reconciliation and finance automation. I have worked with source systems and AI-assisted development. I want to build on that by learning independent forecasting, business drivers and client communication. I have not yet independently managed a complete client forecast.","Which skills have you used professionally, and which are coursework or learning interests?","Show the skills map and open one relevant example, such as the Tax or SQL lesson.")}
function atlasPage(){return '<p class="lead">This roadmap is based on my existing Learning Atlas. These are learning targets, not qualifications I already hold.</p>'+panel("ROADMAP","Finance, data, communication and intelligent automation",flow(["Finance knowledge","Data preparation","Financial analysis","Communicate clearly","Improve processes"])+'<div id="atlas-lab"></div><p>Prioritise the skills needed for client work. Then build more advanced AI and machine learning capability on top of checked data and simple forecasts.</p>')+interview("What are you interested in learning?","I want to get better at forecasting and understanding how a business makes money. My Learning Atlas includes Power BI, SQL, financial modelling and further data skills. I am also interested in agentic AI, machine learning, UI/UX and Figma. Better dashboard design could help clients understand information more quickly. I would first focus on the skills that help me do the job well, then build on them.","Which one would you learn first? Start with forecasting, SQL and reporting foundations; advanced AI is not a replacement for learning the business.","Show the roadmap and one small project you would build.")}
function atlasMount(){let root=$("atlas-lab"),filter="All",icons={"Microsoft PL-300":"powerbi","Google Cloud Associate Data Practitioner":"googlecloud","Python PCEP":"python","UI/UX & Figma":"figma","Tableau Data Analyst":"tableau","Azure AI fundamentals":"microsoftazure","Microsoft Fabric":"microsoft"};function render(){root.innerHTML='<div class="toolbar">'+["All","Finance","Data","Communication","Intelligent automation"].map(v=>'<button data-atlas="'+v+'" class="'+(filter===v?"active":"")+'">'+v+'</button>').join("")+'</div><div class="columns">'+G.atlas.filter(x=>filter==="All"||x[0]===filter).map(v=>'<article class="stat brand-card">'+(icons[v[1]]?logo(v[1],icons[v[1]]):"")+'<small>'+v[0]+' · Planned learning</small><h3>'+esc(v[1])+'</h3><p>'+esc(v[2])+'</p><div class="callout"><b>Small project</b><p>'+esc(v[3])+'</p></div></article>').join("")+'</div><div class="toolbar">'+link("q1/ai","Agentic AI example")+link("q1/ux","UI/UX example")+link("q1/ml","Machine learning example")+'</div>'}root.onclick=e=>{let b=e.target.closest("[data-atlas]");if(b){filter=b.dataset.atlas;render()}};render()}
function techContent(id){let texts={excel:["You need to add sales, find categories and group amounts. Excel can do this before you build a dashboard.","An embedded table with editable cells and four working calculations.","How would you check a monthly report in Excel?","I would use formulas and approved lookup mappings, then compare source totals with the report and inspect missing categories. I would not treat a formula returning a number as proof it is correct."],sql:["Customer A has a $100 invoice and three support tickets. B has a $200 invoice and one ticket. If you join the tables, the A invoice appears three times.","SQL is a language for asking questions about tables. A JOIN matches records; if the matching table has multiple rows, the original amount can be repeated.","How would you combine accounting and CRM data?","I would check what one row represents in each system, agree identifiers and dates, and test the joins. I would compare the source totals to the final output before using them."],bi:["A client wants a report by customer and month, and needs to check the records behind it.","BI means business intelligence. A report should change with filters while maintaining agreed calculations.","How would you design a reliable dashboard?","I would agree the decision and metric definitions first, build a data model with correct relationships, compare the measures against source records and ask the reviewer to test the layout."],ai:["An AI assistant suggests removing duplicate amounts. Two different invoices have the same amount, so the output is wrong.","An AI workflow should have clear permissions, validation and human review before acting.","How do you use AI responsibly?","I use AI to explore approaches and code, but I define the business problem, test the output and investigate discrepancies. I do not share confidential information with unapproved tools."],ux:["A client has only a few minutes. A crowded report makes the key funding risk hard to find.","UI is the interface; UX is the experience of using it. A good layout makes a decision easier to understand.","Why are you interested in Figma and UI/UX?","I want to create reports that are not only accurate but also easy for a client to use. I would prototype a design, ask for feedback and then build it."],ml:["A business wants to predict sales for next month. It is tempting to use a complicated model first.","Machine learning finds patterns in data. Start with a simple forecast and test on data the model has not seen.","How would you evaluate a forecasting model?","I would compare it with a simple baseline on a later period it has not seen, check errors and make sure the data available at prediction time is the data used. I would also consider whether the model is explainable."]};let v=texts[id];return '<p class="lead">'+esc(v[0])+'</p>'+panel("A–D · CONCEPT","Understand the problem",'<p>'+esc(v[1])+'</p>')+panel("E–G · INTERACTIVE LAB","Try it directly on this page",'<div id="technical-lab"></div>')+interview(v[2],v[3],"What can go wrong, and how would you detect it?","Open the working lab, change one setting or record, and explain the check.")}
function mlMount(){let root=$("technical-lab");lab("technical-lab",[["m","Forecast for month 6",130,70,180,5,""],["actual","Actual month 6 (held out)",125,70,180,5,""]],s=>{let vals=[100,110,105,120,115,s.actual],baseline=115;return chart([{name:"Actual sales",vals}],["M1","M2","M3","M4","M5","M6"],"")+table(["Model","Month 6 prediction","Absolute error"],[["Last month baseline",baseline,Math.abs(s.actual-baseline)],["Candidate",s.m,Math.abs(s.actual-s.m)]])+'<p>Months 1–5 are known before forecasting M6. The candidate is a user-supplied example, not a trained ML model. Do not use the held-out actual to choose a prediction and then claim an independent test. A better error on one month does not prove a model is better generally.</p>'})}
function caseOverview(){return '<p class="lead">Explore the real experience behind each challenge. Each demonstration uses original fictional data so I can show the method without exposing employer records.</p>'+panel("EVIDENCE MAP","Choose a challenge",'<label>Find by skill or employer <input id="case-search" type="text" placeholder="Deloitte, errors, communication…" style="width:100%"></label><div id="case-list" class="columns">'+caseNames.map(v=>'<article class="stat" data-search="'+esc(v.join(" ").toLowerCase())+'"><small>'+esc(v[1])+'</small><h3>'+esc(v[2])+'</h3><b style="font-size:20px">'+esc(v[3])+'</b>'+link("q2/"+v[0],"Open simulation")+'</article>').join("")+'</div>')+'<p>Start with Deloitte OCR, Tax automation and overlapping pivots. Then select a challenge that matches the interview question.</p>'}
function caseContent(id){let c=caseNames.find(x=>x[0]===id);return '<div class="eyebrow">'+esc(c[1])+' · CAREER EVIDENCE</div><p class="lead">'+esc(c[4])+'</p>'+panel("A–B · PROBLEM AND EVIDENCE","What I worked on",'<div class="stat"><small>Reported experience / defined scope</small><b>'+esc(c[3])+'</b></div><p>'+esc(c[5])+'</p>'+flow(["Situation","Investigate","Choose approach","Build","Check","Explain outcome"]))+panel("C–G · WATCH IT RUN","Explore each stage",'<div id="case-lab"></div>')+panel("H · INTERVIEW","How I would explain this experience",'<div class="question">Tell me about a time you '+esc(c[2].toLowerCase())+'.</div><details><summary>60–90 second answer</summary><p>'+esc(c[4])+'</p></details><details><summary>30-second answer</summary><p>'+esc(c[4].split(". ").slice(0,2).join(". "))+'.</p></details>'+c[7].split("|").map(x=>detail(x,c[8])).join("")+'<div class="callout"><b>Transfer to FP&A</b><p>'+esc(c[9])+'</p></div><p><b>What to show:</b> walk through the problem, the failed output and the correction above. Explain your own role, AI assistance and the checks; distinguish the fictional recreation from the actual work.</p>')+(id==="teaching"?'<div class="toolbar"><a class="btn" href="https://the-bell.onrender.com/" target="_blank" rel="noopener">The Bell ↗</a><a class="btn" href="https://learning-reporting-in-depth.nabilahazman249.chatgpt.site/" target="_blank" rel="noopener">Public learning examples ↗</a></div>':"")}
function clientContent(id){let v=clients.find(x=>x[0]===id);return '<p class="lead">Fictional client case. Start with the question, not a finished answer.</p>'+panel("A–B · DISCOVERY","Find out what the client needs",'<div id="discovery"></div>')+panel("C–G · ANALYSE AND DECIDE","Use the evidence",'<div id="client-lab"></div>')+interview(v[2],v[9],v[10],"Ask the discovery questions, show the example above and explain how new evidence changes your advice.")+'<div class="callout"><b>What not to do</b><p>'+esc(v[11])+'</p></div>'}
function q3Page(id){if(id==="research")return '<p class="lead">Research is the first part of helping a client. Before opening a spreadsheet, understand what the business sells, how it earns money and what decision matters.</p>'+panel("A–E · RESEARCH CANVAS","The same method, different business",'<div id="research-lab"></div><div id="research-quiz"></div>')+panel("F–G · FIND A USEFUL INSIGHT","Facts are not the same as conclusions",flow(["Reported fact","Possible explanation","Missing evidence","Financial question","Decision"])+'<div class="columns"><div class="stat"><h3>Company says many people signed up</h3><p>That is a reported metric. It does not prove retained paid growth.</p></div><div class="stat"><h3>Investigate the denominator</h3><p>Compare sign-ups, incremental paid conversion, retention and costs. Ask what would reverse the conclusion.</p></div></div><p>Keep public facts, client statements, reconciled records, hypotheses and model assumptions separate. Compare the same customer task across competitors, and follow a change through revenue, cost and cash.</p>'+link("q4/findings","Explore source-backed Canva findings"))+interview("How would you research a new client?","I would start with what the company sells and who pays for it, then look at the industry, competitors and recent changes. I would identify the main business decision and check what information is missing. I would use public research to ask better questions, not pretend to know the client's private numbers.","What surprising insight might you investigate? Compare sign-ups with incremental retained paid users, or compare profit with cash.","Show the research canvas and switch from software to retail.");
if(id==="discovery")return '<p class="lead">The first question is not “What spreadsheet do we need?” It is “What decision are you trying to make?”</p>'+panel("A–G · CLIENT PROCESS","From research to a useful decision",'<div id="research-lab"></div>')+panel("CLIENT QUESTIONS","Ask, listen and adapt",'<ol>'+["What decision do you need to make and when?","What changed, and what matters most?","Which numbers do you have and trust?","Which products, customers or channels drive the change?","What can we compare against?","Which costs or commitments would change?","What happens if we wait or act now?","Who owns the data and who approves the decision?"].map(x=>'<li>'+x+'</li>').join("")+'</ol>'+link("q3/cash-down","Try guided case 1")+link("q4/canva-questions","Apply to Canva"))+interview("What would you ask a client first?","I would ask what decision they need to make, what has changed and what evidence is available. I would listen and adapt my questions rather than use the same model for every client.","What if the client asks for a report but cannot explain why? Ask which decision or audience the report is meant to support.","Use the flow above to explain the method.");
if(id==="review")return '<p class="lead">StudioCo is a fictional subscription business. We first verify the actual results, then explain how they compare with the plan. All amounts are USD.</p>'+panel("A–D · WHAT IS IN A MONTHLY REVIEW?","From source rows to management results",flow(["Source export","Map accounts","Check totals","Actual vs plan","Explain","Review"])+'<p>Revenue is the sales earned. Cost of sales is the direct cost of delivering them. Gross profit is revenue minus cost of sales; operating profit also subtracts operating expenses. A plan is the original target.</p>'+link("q1/profit","Review profit basics"))+panel("E–G · WORKING REVIEW","Investigate source data and rerun",'<div id="review-lab"></div>')+interview("How would you make sure a client report is accurate?","I would agree definitions and reporting periods, check the source records, compare totals independently and investigate missing or duplicated items. I would not release a report with material unresolved issues. Once the data is checked, I would explain variances and forecast assumptions separately.","Why can a reconciled report still give a poor forecast? Historical accuracy does not guarantee assumptions about the future.","Inject a duplicate, trace gross profit, record the correction, then load December.");
if(id==="handover")return '<p class="lead">Make the next month easier without automating away judgement.</p>'+panel("RUNBOOK","Monthly review and handover",flow(["Agree period","Load export","Validate","Explain variance","Update forecast","Review actions"])+'<div class="columns"><div class="stat"><h3>Analyst owns agreed work</h3><p>Refresh, reconcile, draft explanation, document changes and open questions.</p></div><div class="stat"><h3>Escalate to reviewer</h3><p>Material unresolved data, new methods, sensitive advice or commitments outside authority.</p></div></div><p>Keep a decision log: decision, evidence, assumption, owner, next review and trigger to reconsider. Keep original budget and forecast versions.</p>'+link("q3/review","Load next month in the actual review")+link("q2/teaching","Train another analyst"))+interview("How would you train the next analyst?","I would document the process with examples, show how to run checks, let the new analyst investigate a deliberate error and ask them to explain the result. I would agree what they can handle independently and what needs review.","What would change next month? New source data, business assumptions and priorities; reuse definitions only after checking.","Demonstrate the December refresh and the learning-style simulation.");
if(id==="capacity")return '<p class="lead">Inspired Financials provides a service, not software alone. Analyst time is a limited resource. These hours are fictional and do not represent the firm’s actual capacity.</p>'+panel("WORKED EXAMPLE","Compare manual refresh and reusable work",'<p>Six clients × (5 refresh + 3 analysis + 2 exception hours) + 12 onboarding = 72 analyst hours. Founder review is 12 separate hours. Reusable refresh falls to 2 hours/client; maintenance is 4 hours/month.</p><div class="formula">6 × (5 − 2) − 4 = 14 hours saved each month\n24 ÷ 14 ≈ 1.7 months simple time payback</div><div id="capacity-lab"></div>')+interview("Where could you help the founder save time?","I would first ask which parts of client work take the most time. If a repeated refresh is stable and can be checked, I would explore a reusable workflow. I would keep the founder’s judgement and client review separate.","What if maintenance takes longer than time saved? Reconsider whether the solution is worth building.","Change the maintenance hours and discuss why time savings are not guaranteed.");
if(id==="retailer")return '<p class="lead">Transfer the same method to a retailer. Unlike subscription software, a retailer may need to pay for inventory before selling it.</p>'+panel("COMPARE DRIVERS","Different business, same investigation",'<div class="columns"><div class="stat"><h3>Subscription software</h3><p>Paid users × price. Usage, retention, support and AI costs.</p></div><div class="stat"><h3>Retailer</h3><p>Orders × average order value. Product costs, returns, stock and supplier terms.</p></div></div><div id="retail-lab"></div>')+interview("Would you use the same financial model for every client?","No. I would keep the same method of research, checking and decision-making, but use drivers that match the business. For a retailer, I would look at order volume, margin, inventory and supplier payments.","What if more stock is needed to grow? Model payment timing, expected sales and unsold stock risk.","Compare the two business types and change the retail inputs.");return clientContent(id)}
const canvaLessons={
company:["Why I picked Canva","I use Canva Pro for The Bell. I can create lesson carousels, keep a consistent style and publish content without hiring a design team. That made me curious about why a person starts for free, returns and eventually pays.","Canva makes specialist design accessible through software. Inspired Financials makes specialist financial planning accessible through people and technology. Their costs differ: software usage versus analyst and reviewer time.","Why did you choose Canva?","I use it myself for teaching content. I wanted to understand how it gives enough value for people to start for free and still earns enough from paying users to keep improving.","Show the customer journey and explain what creates a repeat workflow."],
plans:["From free user to paying customer","Imagine 1,000 people try a design tool. Only 5% pay. At an illustrative $16 per month, 50 paying customers generate $800 monthly recurring revenue.","Free, Pro, Business and Enterprise are verified plan names. Free lowers the trial barrier; paid tiers may add advanced tools, brand features and collaboration. Enterprise adds organisational controls. Actual prices and plan features vary; no actual Canva price is used here.","How does Canva make money?","It offers free access, then earns recurring revenue from customers and teams who pay for extra value. I would investigate conversion, effective prices, retention and costs rather than assume every user pays.","Change conversion and price; explain the funnel."],
competitors:["What customer job is each product built for?","A teacher wants a carousel. A marketing team wants branded campaigns. A product designer wants an app prototype. These are related but different jobs.","Compare Canva, Adobe Express and Figma by the task, users, paid value, switching effort and AI usage. Do not claim one is universally best.","Who are Canva's competitors?","Adobe Express overlaps on accessible and branded creative work. Figma is especially relevant for collaborative product design. The overlap depends on what the customer is trying to do. I would compare the workflow and value rather than just the price.","Choose a teacher task, then an app prototype."],
retention:["Why keeping customers matters","Start with 1,000 paying customers. 100 join and 5% cancel each month. Month one closes at 1,050.","Acquisition means gaining customers. Conversion is the share that takes an action. Retention is the share that stays; churn is the share that leaves. MRR is monthly recurring revenue; annualized recurring revenue can be 12×MRR, not the same as audited annual revenue.","Why is customer retention important?","New customers may not replace customers who leave. I would look at the customer base over time, revenue per customer and the reasons people renew or cancel.","Increase cancellation to 20% while new customers stay unchanged."],
cost:["How much does another paid customer contribute?","A fictional customer pays $16 monthly and costs $4 monthly to serve. The difference is $12 per paid month, or $60 over five paid months.","Contribution is money left after relevant extra costs. It is not total company profit. Keep free-user activation and setup costs separate so costs are not counted twice.","What is the risk of more AI users?","AI can bring new customers, but it can also increase the cost of serving them. I would measure usage and cost by customer group and check whether the extra paid revenue covers the extra costs.","Change the serving cost from $4 to $10."],
increment:["How much growth is genuinely extra?","A person joins through an AI assistant. Would they have joined Canva anyway? The channel sign-up alone cannot answer this.","MCP is a way for an AI assistant to use supported capabilities of another service with permissions. Incremental means extra growth that would not otherwise happen. Compare comparable groups before claiming cause and effect.","Why aren't AI sign-ups enough?","I would want to know how many users were genuinely added by the channel, how many paid and stayed, and how much they cost to serve. A comparison group can help if it is designed fairly.","Change treatment and comparison conversion rates; explain the difference in percentage points."],
findings:["Find a business question behind public facts","The strongest research question is not just how many users Canva has. It is whether growth in a new channel is worth additional spending.","Reported facts, interpretation and model assumptions have different levels of evidence. Check the period and definition before comparing numbers. Affected employees do not equal departures. A percentage increase does not reveal the starting dollars.","What unexpected insight did you find?","Canva's new AI route can increase both customer acquisition and the cost of serving users. I would test whether the extra paid contribution justifies the spend, and whether the timing creates a funding gap. That is more useful than treating sign-ups alone as success.","Show the reported facts, the missing evidence and the cash timeline."],
pilot:["Should Canva invest more in AI distribution?","The channel already exists. The question is how much additional spending to commit, while protecting accessible free use.","These are invented pilot assumptions, not Canva financial results. First compare contribution scenarios; then break contribution into paid customers, price, months, serving and setup costs; finally model cash dates.","How would you decide whether to scale the pilot?","I would compare extra paid conversion and contribution with spending, then check cash timing and strength of evidence. In this example the base case earns $6,000 but needs extra funding, so I would stage the investment.","Start with the base case; choose Double serving cost, then Delay payment to month 2."],
decision:["A recommendation is more than a number","A positive six-month result does not prove the investment should be approved today.","Check contribution, cash reserve and actual evidence separately. Management approval remains separate. Protect free accessibility and test paid value or usage-based add-ons before making a large commitment.","What would change your recommendation?","Lower incremental conversion, weaker retention, higher serving costs or insufficient cash would change it. I would ask for actual cohort evidence and payment timing before scaling. I would also test whether the next group performs similarly.","Use the same investment model to change assumptions, then explain the three gates."]
};
function q4Page(id){if(id==="canva-questions")return '<p class="lead">Research helps identify the right questions. It does not replace talking to management.</p>'+panel("CLIENT DISCOVERY","Seven questions to ask Canva",'<div id="canva-ask"></div>')+interview("What data would you ask for first?","I would start with the decision and outcome, then ask for customer and channel information and a credible comparison. I would want conversion, retention, costs and payment timing before replacing the fictional assumptions.","Which missing input could reverse your decision? Incremental conversion, paid lifetime or cost to serve.","Link each question to the related learning model.");
if(id==="defence")return '<p class="lead">Use the same visuals you studied. There is no separate presentation mode or downloaded deck.</p>'+panel("90 SECONDS","A short company explanation",'<p>“I chose Canva because I use it for The Bell. Free access makes it easy to start, while repeat paid workflows can create recurring revenue. The company has expanded AI-assisted distribution, but sign-ups do not tell us how much extra paid value it creates. I would test conversion, retention, serving costs and cash before increasing spend. My fictional model shows positive contribution can still leave a funding gap.”</p>'+link("q4/company","Customer journey")+link("q4/pilot","Model"))+panel("5–7 MINUTES","Suggested route",flow(["Why Canva","Competitors","Reported findings","Model change","Decision"])+'<div class="toolbar">'+link("q4/company","1. Why Canva")+link("q4/competitors","2. Competitors")+link("q4/findings","3. Research")+link("q4/pilot","4. Model")+link("q4/decision","5. Recommendation")+'</div>')+panel("FOUNDER FOLLOW-UPS","Defend assumptions in plain English",["Why 6%?|It is a fictional incremental conversion assumption, not a Canva rate. I would replace it with actual comparable-group evidence.","What if AI serving cost doubles?|With $8 monthly cost, 600 × 5 × ($16 − $8) − $30,000 = −$6,000.","Why not scale after +$6k?|The model has a funding gap and assumptions need evidence. A positive expected return does not authorize spending.","Why not raise price?|Test willingness to pay, plan mix, cancellation and competitor alternatives.","What if users would have joined anyway?|Then incremental conversion is lower and the benefit may not cover cost.","What if restructuring savings are delayed?|Separate one-time payments and later possible savings; do not claim private amounts.","How does this apply to Inspired Financials?|Research the client, check the data, choose relevant drivers and explain a decision. Service delivery depends on analyst time rather than only software usage."].map(v=>{let a=v.split("|");return detail(a[0],a[1])}).join(""));
let v=canvaLessons[id];return '<p class="lead">'+esc(v[1])+'</p>'+panel("A–D · UNDERSTAND",v[0],'<p>'+esc(v[2])+'</p>'+(id==="company"?'<div class="columns"><div class="stat brand-card">'+logo("Canva","canva")+'<h3>Canva</h3><p>Accessible design through software.</p></div><div class="stat"><h3>Inspired Financials</h3><p>Accessible financial planning through expertise and analyst time.</p></div></div>':id==="plans"?'<div class="four">'+["Free","Pro","Business","Enterprise"].map((n,i)=>'<div class="stat"><small>Tier '+(i+1)+'</small><h3>'+n+'</h3><p>'+["Try core tools","Extra individual value","Growing teams","Organisation controls"][i]+'</p></div>').join("")+'</div>'+source("https://www.canva.com/pricing/","Official plan comparison"):""))+panel("E–G · LEARN BY DOING","Explore the example",'<div id="canva-lab"></div>')+interview(v[3],v[4],"What extra data would you need before using this example for a real company? What could reverse your conclusion?",v[5])}
function canvaAsk(){let root=$("canva-ask"),arr=[["What decision do we need to make, by when?","Agree reach, paid growth, contribution, cash or another outcome.","decision"],["Which customers and channels are driving change?","Unique users, existing vs new, origin and comparable group.","increment"],["What can we compare against?","Activation, conversion, retention and cost for AI route vs direct route.","retention"],["What does heavy AI usage cost?","Usage distribution and cost by free/paid group.","cost"],["Why do customers upgrade or leave?","Plan, task, price, competitor and customer interviews.","competitors"],["How much can we test, and what would make us stop?","Spend, cash reserve, decision gates and what remains free.","pilot"],["Who owns the data?","Agree definitions, reporting periods and reconciliations.","findings"]];root.innerHTML=arr.map((v,i)=>'<details><summary>'+esc(v[0])+'</summary><p><b>Evidence needed:</b> '+esc(v[1])+'</p>'+link("q4/"+v[2],"Open related lesson")+'</details>').join("")}
function q5Page(id){if(id==="firm")return '<p class="lead">Inspired Financials describes outsourced FP&A on a rolling monthly subscription. The advertised role is designed to learn through real client work alongside founder James Blandford.</p>'+panel("RESEARCH","Understand the business and role",flow(["Founder expertise","Coached analyst","Agreed independent work","Document process","Train future colleagues"])+'<p>The company offers financial planning, analysis and decision support. Do not assume its internal prices, margins, workload or client list. Ask how the role develops and which responsibilities come first.</p>'+source("https://uk.linkedin.com/company/inspired-financials","Company profile")+source("https://my.linkedin.com/jobs/view/fp-a-analyst-at-inspired-financials-4488666566","Role advertisement")+source("https://www.inspiredfinancials.com/","Company website"))+interview("Why Inspired Financials?","I want to move from reliable reporting into understanding how businesses make decisions. Learning directly from an experienced finance leader and working with different clients appeals to me. I can contribute my accounting, reporting and process skills while building my FP&A experience.","Why should I hire someone without independent FP&A ownership? I bring transferable accounting, data and validation experience, and I want to learn the commercial side under review.","Show the learning path and ask about expectations.");
if(id==="reflection")return '<p class="lead">Optional browser-only reflection. Hide practice notes before sharing. This is not private authenticated storage.</p><div class="practice-only">'+panel("REFLECTION","What do I still need to understand?",'<div id="reflection-lab"></div><p>Do not treat these ratings as objective. Unknown stays unknown. Do not enter sensitive details.</p>')+'</div>';
return '<p class="lead">Prioritise success, coaching, independent work and commercial judgement. Ask follow-up questions naturally rather than reading a long list.</p>'+panel("TOP QUESTIONS","Ask James",'<div id="question-lab"></div>')+panel("HOW TO LISTEN","Use the answer to understand fit",flow(["Ask","Listen","Clarify","Record unknowns","Reflect privately"])+'<p>Questions are a conversation, not a test. If he explains one topic naturally, skip the repeated question. Do not assume his answers in advance.</p>')}
function questionsMount(){let root=$("question-lab");root.innerHTML=C.questions.map((v,i)=>'<article class="panel" style="margin:10px 0"><div class="step-title">'+(i<4?"Priority question":"If time allows")+' · '+esc(v[0])+'</div><h3>'+esc(v[1].replace(/envisage coaching me through/g,"see us working together while I learn"))+'</h3><details><summary>Follow-up and why ask</summary><p>'+esc(v[2])+' This helps you understand '+esc(v[0].toLowerCase())+' before making assumptions about the role.</p></details></article>').join("")}
function reflectionMount(){let r=$("reflection-lab"),v=notes.reflection||{};r.innerHTML=["Coaching","Autonomy and trust","Workload","FP&A development","Progression","Employment terms"].map((t,i)=>'<label class="field"><span>'+t+'</span><select data-rating="'+i+'">'+["Unknown","1","2","3","4","5"].map(x=>'<option '+(v[i]===x?"selected":"")+'>'+x+'</option>').join("")+'</select></label>').join("")+'<button id="save-reflection">Save local reflection</button>';r.querySelector("#save-reflection").onclick=()=>{notes.reflection=Object.fromEntries([...r.querySelectorAll("[data-rating]")].map(x=>[x.dataset.rating,x.value]));save();r.querySelector("#save-reflection").textContent="Saved on this browser"}}
function rehearse(){return '<div class="trail"><a href="#home">Home</a> › Rehearsal</div><div class="hero"><div class="eyebrow">Practice after the five topics</div><h1>Explain it in your own words</h1><p class="lead">Use the same lessons and visuals. Suggested practice: 5 minutes introduction, 10 skills, 10 experience, 15 clients, 10 company, 10 questions. Not James’s confirmed schedule.</p></div><div class="panel"><h2>Mock interview</h2><div id="mock-lab"></div></div><div class="panel"><h2>How to use the site when asked</h2>'+G.chapters.map((v,i)=>'<p><b>Question '+(i+1)+':</b> '+esc(v[2])+' '+link("q"+(i+1)+"/"+v[3],"Open the same lesson")+'</p>').join("")+'<p>If the internet fails, explain the example without the site. You do not need any downloads.</p></div>'}
function mockMount(){let r=$("mock-lab"),idx=0,arr=C.mocks.concat([["Fit","Why hire you without independent FP&A experience?","I bring accounting, reporting, validation and process improvement experience. I want to learn the commercial side with appropriate review."],["Learning","How would you learn a new client process?","Understand decision, source data and definitions, try a small example, check output and document."],["Feedback","What would you do differently next time?","Use a genuine case. Explain a concrete improvement, such as earlier source checks or clearer documentation. Do not invent a past failure."]]),routes=["q5/firm","q1/skills","q2/tax","q1/ai","q3/cash-down","q3/deadlines","q4/defence","q2/pivot","q5/firm","q5/questions","q1/q1-answer","q3/discovery","q2/overview"];function render(){let v=arr[idx];r.innerHTML='<div class="step-title">'+esc(v[0])+' · Question '+(idx+1)+' of '+arr.length+'</div><h3>'+esc(v[1])+'</h3><label>Answer before opening guidance<textarea placeholder="Try your own answer first. Not saved."></textarea></label>'+detail("Reveal answer guidance",v[2])+detail("Challenge yourself","Was the answer direct? Did I use verified evidence, explain why it matters, state what I still need to learn and avoid overclaiming?")+link(routes[idx]||"home","Review the exact lesson")+'<div class="footer-nav"><button data-mock="-1" '+(!idx?"disabled":"")+'>← Previous</button><button data-mock="1" '+(idx===arr.length-1?"disabled":"")+'>Next →</button></div>'}r.onclick=e=>{let b=e.target.closest("[data-mock]");if(b){idx=Math.max(0,Math.min(arr.length-1,idx+Number(b.dataset.mock)));render()}};render()}
function notesMount(){if(!$("save-note"))return;$("save-note").onclick=()=>{notes[route]={text:$("practice-answer").value,ready:$("readiness").value};save();$("note-status").textContent="Saved on this browser."};$("clear-note").onclick=()=>{delete notes[route];save();$("practice-answer").value="";$("readiness").value="Not started";$("note-status").textContent="Cleared."};$("clear-all").onclick=()=>{if(confirm("Clear all practice notes and reflection saved on this browser?")){notes={};save();$("practice-answer").value="";$("readiness").value="Not started";$("note-status").textContent="All local notes cleared."}}}
function mount(q,id){if(q==="q1"){if(id==="atlas")atlasMount();else if(id==="orientation"||finance.some(v=>v[0]===id))U.mountFinance(id);else if(id==="ml")mlMount();else if(GTech[id])GTech[id]()}
if(q==="q2"){if(id==="overview")$("case-search").oninput=e=>document.querySelectorAll("[data-search]").forEach(x=>x.hidden=!x.dataset.search.includes(e.target.value.toLowerCase()));else GCases.caseMount(id)}
if(q==="q3"){if(id==="research")GCanva.researchMethod();else if(id==="discovery")GCanva.discovery();else if(id==="review")GTech.review();else if(id==="capacity")GTech.capacity();else if(id==="retailer")lab("retail-lab",[["orders","Orders",100,0,300,5,""],["aov","Average order value",30,0,100,1,"$"],["cost","Product and fulfilment per order",18,0,80,1,"$"],["stock","Stock cash paid upfront",2500,0,6000,100,"$"]],s=>stat("Revenue",money(s.orders*s.aov))+stat("Gross contribution",money(s.orders*(s.aov-s.cost)))+stat("Stock cash commitment",money(s.stock),"Separate from recognition")+bars([["Sales",s.orders*s.aov],["Product cost",-s.orders*s.cost],["Stock paid",-s.stock]])+'<p>Check unsold stock, collection dates and supplier terms. Stock cash payment is not automatically current expense.</p>');else if(clients.some(v=>v[0]===id))GCases.mountClient(id)}
if(q==="q4"){if(id==="canva-questions")canvaAsk();else if(id==="decision")GCanva.pilot();else if(GCanva[id])GCanva[id]()}
if(q==="q5"){if(id==="questions")questionsMount();if(id==="reflection")reflectionMount()}notesMount()}
function render(){route=location.hash.slice(1)||"home";let [q,id]=route.split("/");if(q!=="home"&&q!=="rehearse"&&(!items[q]||!items[q].some(x=>x[0]===id))){route="home";q="home";history.replaceState(null,"","#home")}nav();let body="";if(q==="home")body=home();else if(q==="rehearse")body=rehearse();else{if(q==="q1"){if(id==="skills")body=skillPage();else if(id==="atlas")body=atlasPage();else if(id==="q1-answer")body=panel("ANSWER","My skills and learning interests",'<p>My current strengths are accounting, financial reporting, Excel, Tableau, reconciliations and finance automation. I want to build on them through driver-based forecasting, financial modelling and understanding commercial decisions. My Learning Atlas includes Power BI, SQL, FP&A and other data skills. I am also interested in agentic AI, machine learning, UI/UX and Figma. I want to build useful, reliable and understandable finance work.</p>'+flow(["First 30 days: learn standards","Next: own agreed refreshes","Later: increase ownership"])+'<p>This is a suggested learning progression, not an agreed employer timetable.</p>'+link("q1/atlas","Learning Atlas")+link("q2/overview","Career evidence"));else if(id==="orientation"||finance.some(v=>v[0]===id))body=financeContent(id);else body=techContent(id)}if(q==="q2")body=id==="overview"?caseOverview():caseContent(id);if(q==="q3")body=q3Page(id);if(q==="q4")body=q4Page(id);if(q==="q5")body=q5Page(id);body=shell(q,id,body)}$("app").innerHTML=body;document.body.classList.toggle("sharing",sharing);if(q==="rehearse")mockMount();else if(items[q])mount(q,id);if(q!=="home")GTutor.enhance(route);window.scrollTo(0,0);document.title=(q==="home"?"Interview learning studio":q==="rehearse"?"Interview rehearsal":items[q].find(x=>x[0]===id)[1])+" | Bell"}
$("share").onclick=()=>{sharing=!sharing;document.body.classList.toggle("sharing",sharing);$("share").textContent=sharing?"Show practice notes":"Hide practice notes";$("share").setAttribute("aria-pressed",String(sharing))};window.addEventListener("hashchange",render);render();
})();